1	//! `vocab` — the palette256² word vocabulary.
2	//!
3	//! ## What changed from DeepNSM v1
4	//!
5	//! v1 used a flat 4,096-word COCA table (12-bit ids) with a `4096²` u8 distance
6	//! matrix. v2 carves the id space as a **256×256 palette tile**: a word id is a
7	//! `(basin, identity)` byte pair — `basin = id >> 8`, `identity = id & 0xFF` —
8	//! so the id IS the address into the palette256² distance table
9	//! ([`crate::space`]). Capacity is `65_536`; the ~20k academic vocabulary (the
10	//! `80 × 256` carve the plan names) fits with room to spare.
11	//!
12	//! ## `vocabulary = frequency × distance`
13	//!
14	//! The two bytes are not arbitrary. Per the operator ruling the vocabulary is
15	//! `frequency × distance`: the **basin** (high byte) is the frequency-rank band
16	//! (coarse — words in the same 256-wide band share a basin), and the
17	//! **identity** (low byte) is the within-band position. Assigning ids in
18	//! descending frequency order therefore puts high-frequency words in low basins
19	//! and makes basin-adjacency a frequency proxy — while the *semantic* distance
20	//! between two ids comes from the trained codebook in [`crate::space`], never
21	//! from the id arithmetic itself.
22	
23	/// A word id in the `256×256` palette tile.
24	///
25	/// Stored as a `u16`; the `(basin, identity)` split is `(id >> 8, id & 0xFF)`.
26	pub type WordId = u16;
27	
28	/// Split a [`WordId`] into its `(basin, identity)` palette byte pair.
29	#[inline]
30	#[must_use]
31	pub const fn split(id: WordId) -> (u8, u8) {
32	    ((id >> 8) as u8, (id & 0xFF) as u8)
33	}
34	
35	/// Recombine a `(basin, identity)` byte pair into a [`WordId`].
36	#[inline]
37	#[must_use]
38	pub const fn join(basin: u8, identity: u8) -> WordId {
39	    ((basin as u16) << 8) | identity as u16
40	}
41	
42	/// The frequency-ranked palette vocabulary.
43	///
44	/// Words are inserted in **descending frequency order** (most frequent first),
45	/// so the first 256 words occupy basin 0, the next 256 basin 1, and so on.
46	#[derive(Debug, Clone, Default)]
47	pub struct PaletteVocab {
48	    /// Insertion-ordered words (index == [`WordId`]).
49	    words: Vec<String>,
50	    /// Reverse map word → id, for tokenization.
51	    index: std::collections::HashMap<String, WordId>,
52	}
53	
54	impl PaletteVocab {
55	    /// Maximum representable vocabulary size (the full `256×256` tile).
56	    pub const CAPACITY: usize = 65_536;
57	
58	    /// The `80 × 256` academic-vocab carve the plan names (§8): basins `0..80`.
59	    pub const ACADEMIC_20K: usize = 80 * 256;
60	
61	    /// Empty vocabulary.
62	    #[must_use]
63	    pub fn new() -> Self {
64	        Self::default()
65	    }
66	
67	    /// Build from a frequency-ranked word list (most frequent FIRST). Words past
68	    /// [`CAPACITY`](Self::CAPACITY) are dropped (the tile is full); duplicates
69	    /// keep their first id. Returns the number of words admitted.
70	    pub fn from_frequency_ranked<I, S>(&mut self, words: I) -> usize
71	    where
72	        I: IntoIterator<Item = S>,
73	        S: Into<String>,
74	    {
75	        for w in words {
76	            if self.words.len() >= Self::CAPACITY {
77	                break;
78	            }
79	            let w = w.into();
80	            if !self.index.contains_key(&w) {
81	                let id = self.words.len() as WordId;
82	                self.index.insert(w.clone(), id);
83	                self.words.push(w);
84	            }
85	        }
86	        self.words.len()
87	    }
88	
89	    /// Number of words in the vocabulary.
90	    #[must_use]
91	    pub fn len(&self) -> usize {
92	        self.words.len()
93	    }
94	
95	    /// Whether the vocabulary is empty.
96	    #[must_use]
97	    pub fn is_empty(&self) -> bool {
98	        self.words.is_empty()
99	    }
100	
101	    /// Look up a word's [`WordId`] (exact match; caller lowercases/normalizes).
102	    #[must_use]
103	    pub fn id(&self, word: &str) -> Option<WordId> {
104	        self.index.get(word).copied()
105	    }
106	
107	    /// The word for a [`WordId`], if in range.
108	    #[must_use]
109	    pub fn word(&self, id: WordId) -> Option<&str> {
110	        self.words.get(id as usize).map(String::as_str)
111	    }
112	
113	    /// The `(basin, identity)` palette pair for a word, via [`split`].
114	    #[must_use]
115	    pub fn pair(&self, word: &str) -> Option<(u8, u8)> {
116	        self.id(word).map(split)
117	    }
118	}
119	
120	#[cfg(test)]
121	mod tests {
122	    use super::*;
123	
124	    #[test]
125	    fn split_join_round_trip() {
126	        for id in [0u16, 1, 255, 256, 257, 20_479, 65_535] {
127	            let (b, i) = split(id);
128	            assert_eq!(join(b, i), id);
129	        }
130	    }
131	
132	    #[test]
133	    fn frequency_rank_fills_basins_in_order() {
134	        let mut v = PaletteVocab::new();
135	        // 300 synthetic words, most-frequent first.
136	        let words: Vec<String> = (0..300).map(|i| format!("w{i}")).collect();
137	        assert_eq!(v.from_frequency_ranked(words), 300);
138	        // word 0 (most frequent) → basin 0; word 256 → basin 1.
139	        assert_eq!(v.pair("w0"), Some((0, 0)));
140	        assert_eq!(v.pair("w255"), Some((0, 255)));
141	        assert_eq!(v.pair("w256"), Some((1, 0)));
142	        assert_eq!(v.pair("w299"), Some((1, 43)));
143	    }
144	
145	    #[test]
146	    fn duplicates_keep_first_id() {
147	        let mut v = PaletteVocab::new();
148	        v.from_frequency_ranked(["the", "cat", "the", "dog"]);
149	        assert_eq!(v.len(), 3);
150	        assert_eq!(v.id("the"), Some(0));
151	        assert_eq!(v.id("dog"), Some(2));
152	    }
153	
154	    /// The companion the synthetic carve test cannot be: its fixture is
155	    /// all-distinct by construction, so it measures the RESERVATION and can
156	    /// never see a fill shortfall.
157	    ///
158	    /// Real `academic_20k.csv` is 20,845 rows but only **18,559 distinct
159	    /// surface forms** (2,286 duplicates — COCA lists a word once per part of
160	    /// speech), and `from_frequency_ranked` admits by surface form. So the
161	    /// academic carve fills 90.6% and basins 73..79 stay empty
162	    /// (`E-ACADEMIC-CARVE-UNDERFILLS-ROWS-ARE-NOT-WORDS-1`, 2026-08-21).
163	    ///
164	    /// This pins the mechanism at unit scale: duplicates consume RANKS but not
165	    /// SLOTS, so the last admitted id is strictly below the input length and
166	    /// the reserved tail is unreachable. Falsified by deleting the
167	    /// `contains_key` guard in `from_frequency_ranked` — the admitted count
168	    /// then equals the input length and both assertions fail.
169	    #[test]
170	    fn duplicates_consume_ranks_but_not_slots_so_the_carve_underfills() {
171	        let mut v = PaletteVocab::new();
172	        // 300 ranks; the 100 multiples of 3 are all the SAME word, so the
173	        // distinct set is 200 unique `w` forms + one `the` = 201.
174	        let words: Vec<String> = (0..300)
175	            .map(|i| {
176	                if i % 3 == 0 {
177	                    "the".to_string()
178	                } else {
179	                    format!("w{i}")
180	                }
181	            })
182	            .collect();
183	        let admitted = v.from_frequency_ranked(words);
184	        assert_eq!(admitted, 201, "duplicates must not consume slots");
185	        // The anti-vacuity half: the fixture really does contain duplicates,
186	        // so a dedupe-free implementation would differ here.
187	        assert!(admitted < 300, "fixture has nothing to deduplicate");
188	        // The consequence that matters: the tail of the reserved range is
189	        // unreachable from this input.
190	        assert_eq!(v.pair("the"), Some((0, 0)));
191	        // 99 duplicate ranks were skipped before it, so the last input word
192	        // lands 99 slots below its own rank.
193	        assert_eq!(v.id("w299"), Some(200));
194	        assert!(
195	            v.len() < 300,
196	            "last admitted id sits below the input length -- the reserved tail is empty"
197	        );
198	    }
199	
200	    #[test]
201	    fn academic_20k_carve_spans_80_basins() {
202	        // The 80×256 academic carve fills basins 0..80 in frequency order.
203	        let mut v = PaletteVocab::new();
204	        let words: Vec<String> = (0..PaletteVocab::ACADEMIC_20K)
205	            .map(|i| format!("w{i}"))
206	            .collect();
207	        assert_eq!(v.from_frequency_ranked(words), 20_480);
208	        assert_eq!(v.pair("w0"), Some((0, 0))); // most frequent → basin 0
209	        assert_eq!(v.pair("w20479"), Some((79, 255))); // last academic → basin 79
210	    }
211	}
