1	//! Unified tokenizer registry for cross-model calibration.
2	//!
3	//! Each model has its own tokenizer (different vocab, different BPE).
4	//! The registry loads all tokenizers and provides uniform access:
5	//!
6	//! ```text
7	//! "The wound is where the light enters"
8	//!   → XLM-RoBERTa (Jina v3):    [581, 36735, 83, 7, ...]  (250K vocab)
9	//!   → XLM-RoBERTa (BGE-M3):     [581, 36735, 83, 7, ...]  (same tokenizer)
10	//!   → Qwen2 (Reranker):          [785, 11980, 374, ...]    (151K vocab)
11	//!   → Qwen3 (Jina v5):           [785, 11980, 374, ...]    (151K vocab, similar to Qwen2)
12	//! ```
13	//!
14	//! Cross-model eval: same text → different token_ids → different codebook lookups
15	//! → compare distances → Spearman ρ between models.
16	
17	/// Model identifier for tokenizer lookup.
18	#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
19	pub enum ModelId {
20	    /// Jina v3 — XLM-RoBERTa tokenizer (250,002 vocab)
21	    JinaV3,
22	    /// BGE-M3 — XLM-RoBERTa tokenizer (250,002 vocab, same as Jina v3)
23	    BgeM3,
24	    /// Jina Reranker v3 — Qwen2 tokenizer (151,936 vocab)
25	    Reranker,
26	    /// Jina v5 text-small — Qwen3 tokenizer (151,936 vocab)
27	    JinaV5,
28	    /// Reader-LM 1.5B — Qwen2 tokenizer (151,936 vocab)
29	    ReaderLm,
30	    /// Qwopus 27B — Qwen2 tokenizer (151,936 vocab)
31	    Qwopus,
32	    /// ModernBERT-large — OLMo tokenizer (50,368 vocab, code-friendly)
33	    /// GeGLU FFN (same gate modulation as SiLU), RoPE, 28 layers × 2624 dim.
34	    /// ONNX available: ort-community/ModernBERT-large-ONNX-ORT (FP32/FP16/INT8/UINT8)
35	    ModernBert,
36	    /// CLIP ViT-Huge-14 — vision encoder, XLM-RoBERTa text side (250,002 vocab)
37	    /// FP32: Kijai/WanVideo_comfy (2.53 GB), BF16: DeepBeepMeep/Wan2.1 (2.39 GB)
38	    ClipVision,
39	}
40	
41	impl ModelId {
42	    /// Vocab size for this model.
43	    pub fn vocab_size(self) -> u32 {
44	        match self {
45	            ModelId::JinaV3 | ModelId::BgeM3 | ModelId::ClipVision => 250_002,
46	            ModelId::Reranker | ModelId::JinaV5 | ModelId::ReaderLm | ModelId::Qwopus => 151_936,
47	            ModelId::ModernBert => 50_368,
48	        }
49	    }
50	
51	    /// Default tokenizer file path (relative to crate root).
52	    /// Tries local ONNX dirs first, then HDR dirs, then from_pretrained fallback.
53	    pub fn tokenizer_path(self) -> &'static str {
54	        match self {
55	            ModelId::JinaV3 | ModelId::BgeM3 | ModelId::ClipVision => {
56	                "crates/thinking-engine/data/jina-v3-hdr/tokenizer.json"
57	            }
58	            ModelId::Reranker => "crates/thinking-engine/data/jina-v5-onnx/tokenizer.json", // Qwen3 (same as v5)
59	            ModelId::ReaderLm | ModelId::Qwopus => {
60	                "crates/thinking-engine/data/Qwopus3.5-27B-v3-BF16-silu/tokenizer.json"
61	            } // Qwen2
62	            ModelId::JinaV5 => "crates/thinking-engine/data/jina-v5-onnx/tokenizer.json",
63	            ModelId::ModernBert => "crates/thinking-engine/data/modernbert-onnx/tokenizer.json",
64	        }
65	    }
66	
67	    /// HuggingFace model ID for from_pretrained fallback.
68	    pub fn hf_model_id(self) -> &'static str {
69	        match self {
70	            ModelId::JinaV3 => "jinaai/jina-embeddings-v3",
71	            ModelId::BgeM3 => "BAAI/bge-m3",
72	            ModelId::Reranker => "jinaai/jina-reranker-v3",
73	            ModelId::JinaV5 => "jinaai/jina-embeddings-v5-text-small-text-matching",
74	            ModelId::ReaderLm => "jinaai/reader-lm-1.5b",
75	            ModelId::Qwopus => "Qwen/Qwen2.5-32B",
76	            ModelId::ModernBert => "answerdotai/ModernBERT-large",
77	            ModelId::ClipVision => "Kijai/WanVideo_comfy",
78	        }
79	    }
80	
81	    /// ONNX model path (for ground truth forward pass).
82	    pub fn onnx_path(self) -> Option<&'static str> {
83	        match self {
84	            ModelId::JinaV5 => Some("crates/thinking-engine/data/jina-v5-onnx/model.onnx"),
85	            ModelId::ModernBert => Some("crates/thinking-engine/data/modernbert-onnx/model.onnx"),
86	            _ => None,
87	        }
88	    }
89	
90	    /// config.json path (for auto-detect architecture).
91	    pub fn config_path(self) -> Option<&'static str> {
92	        match self {
93	            ModelId::JinaV5 => Some("crates/thinking-engine/data/jina-v5-onnx/config.json"),
94	            ModelId::ModernBert => Some("crates/thinking-engine/data/modernbert-onnx/config.json"),
95	            _ => None,
96	        }
97	    }
98	
99	    /// Whether this model has GeGLU/SiLU gate modulation (the 33% correction).
100	    pub fn has_gate_modulation(self) -> bool {
101	        match self {
102	            // GeGLU: ModernBERT, Qwen, Qwopus — all have gated FFN
103	            ModelId::ModernBert | ModelId::Qwopus | ModelId::JinaV5 | ModelId::ReaderLm => true,
104	            // Reranker v3 = Qwen3 base (silu) — HAS gate modulation
105	            ModelId::Reranker => true,
106	            // Standard GeLU: BERT, XLM-RoBERTa — no gate
107	            ModelId::JinaV3 | ModelId::BgeM3 => false,
108	            // Vision: ViT uses standard FFN
109	            ModelId::ClipVision => false,
110	        }
111	    }
112	
113	    /// ONNX availability for this model.
114	    pub fn onnx_repo(self) -> Option<&'static str> {
115	        match self {
116	            ModelId::ModernBert => Some("ort-community/ModernBERT-large-ONNX-ORT"),
117	            ModelId::JinaV5 => Some("jinaai/jina-embeddings-v5-text-small-text-matching"),
118	            ModelId::Reranker => Some("jinaai/jina-reranker-v3"),
119	            _ => None,
120	        }
121	    }
122	}
123	
124	/// Registry holding loaded tokenizers for all models.
125	pub struct TokenizerRegistry {
126	    entries: Vec<(ModelId, tokenizers::Tokenizer)>,
127	}
128	
129	impl TokenizerRegistry {
130	    /// Create empty registry.
131	    pub fn new() -> Self {
132	        Self {
133	            entries: Vec::new(),
134	        }
135	    }
136	
137	    /// Load a tokenizer for a model. Tries local file first, then from_pretrained.
138	    pub fn load(&mut self, model: ModelId) -> Result<(), String> {
139	        // Skip if already loaded
140	        if self.entries.iter().any(|(m, _)| *m == model) {
141	            return Ok(());
142	        }
143	
144	        let path = model.tokenizer_path();
145	        if let Ok(tok) = tokenizers::Tokenizer::from_file(path) {
146	            eprintln!("  [{}] Loaded from {}", model.name(), path);
147	            self.entries.push((model, tok));
148	            return Ok(());
149	        }
150	
151	        // Try from_pretrained (needs network)
152	        let hf_id = model.hf_model_id();
153	        eprintln!("  [{}] Downloading from {}...", model.name(), hf_id);
154	        match tokenizers::Tokenizer::from_pretrained(hf_id, None) {
155	            Ok(tok) => {
156	                // Save for next time
157	                let _ = tok.save(path, false);
158	                self.entries.push((model, tok));
159	                Ok(())
160	            }
161	            Err(e) => Err(format!(
162	                "[{}] Failed to load tokenizer: {}",
163	                model.name(),
164	                e
165	            )),
166	        }
167	    }
168	
169	    /// Load all known models. Returns list of failures.
170	    pub fn load_all(&mut self) -> Vec<String> {
171	        let models = [
172	            ModelId::JinaV3,
173	            ModelId::BgeM3,
174	            ModelId::Reranker,
175	            ModelId::JinaV5,
176	            ModelId::ReaderLm,
177	            ModelId::Qwopus,
178	            ModelId::ModernBert,
179	            ModelId::ClipVision,
180	        ];
181	        let mut failures = Vec::new();
182	        for m in models {
183	            if let Err(e) = self.load(m) {
184	                failures.push(e);
185	            }
186	        }
187	        failures
188	    }
189	
190	    /// Tokenize text through a specific model's tokenizer.
191	    pub fn encode(&self, model: ModelId, text: &str) -> Option<Vec<u32>> {
192	        self.entries
193	            .iter()
194	            .find(|(m, _)| *m == model)
195	            .and_then(|(_, tok)| tok.encode(text, true).ok())
196	            .map(|enc| enc.get_ids().to_vec())
197	    }
198	
199	    /// Tokenize text through ALL loaded models. Returns (model, token_ids) pairs.
200	    pub fn encode_all(&self, text: &str) -> Vec<(ModelId, Vec<u32>)> {
201	        self.entries
202	            .iter()
203	            .filter_map(|(model, tok)| {
204	                tok.encode(text, true)
205	                    .ok()
206	                    .map(|enc| (*model, enc.get_ids().to_vec()))
207	            })
208	            .collect()
209	    }
210	
211	    /// Number of loaded tokenizers.
212	    pub fn loaded_count(&self) -> usize {
213	        self.entries.len()
214	    }
215	
216	    /// Check if a model's tokenizer is loaded.
217	    pub fn is_loaded(&self, model: ModelId) -> bool {
218	        self.entries.iter().any(|(m, _)| *m == model)
219	    }
220	}
221	
222	impl Default for TokenizerRegistry {
223	    fn default() -> Self {
224	        Self::new()
225	    }
226	}
227	
228	impl ModelId {
229	    fn name(self) -> &'static str {
230	        match self {
231	            ModelId::JinaV3 => "jina-v3",
232	            ModelId::BgeM3 => "bge-m3",
233	            ModelId::Reranker => "reranker",
234	            ModelId::JinaV5 => "jina-v5",
