1	//! # Text-to-Thought Lookup
2	//!
3	//! The complete pipeline from text to thought in one struct:
4	//! ```text
5	//! text → tokenizer (BPE) → token_ids
6	//!   → codebook_index (token_id → centroid row)
7	//!   → perturb(engine) → think(N cycles) → commit()
8	//! ```
9	//!
10	//! No forward pass. No weights. Just lookup + MatVec.
11	
12	use crate::codebook_index::CodebookIndex;
13	use crate::dto::BusDto;
14	use crate::engine::ThinkingEngine;
15	
16	/// Complete text-to-thought pipeline.
17	///
18	/// Owns: tokenizer, codebook index, distance table, engine.
19	/// One call: `think("some text") → BusDto`.
20	pub struct TextToThought {
21	    tokenizer: tokenizers::Tokenizer,
22	    codebook: CodebookIndex,
23	    engine: ThinkingEngine,
24	    /// Table size (N in N×N).
25	    pub table_size: usize,
26	    /// Model name.
27	    pub model: String,
28	}
29	
30	/// Stats from a single thought.
31	pub struct ThoughtResult {
32	    pub bus: BusDto,
33	    pub token_count: usize,
34	    pub unique_atoms: usize,
35	    pub entropy: f32,
36	    pub active_count: usize,
37	    pub think_micros: u64,
38	}
39	
40	impl TextToThought {
41	    /// Load from files on disk.
42	    ///
43	    /// - `tokenizer_path`: path to tokenizer.json (e.g. /tmp/bge-m3-tokenizer.json)
44	    /// - `codebook_path`: path to codebook_index.u16 (e.g. /tmp/codebooks/.../codebook_index.u16)
45	    /// - `table_path`: path to distance_table_NxN.u8
46	    /// - `table_size`: N (e.g. 1024 for attn_q, 4096 for ffn_down)
47	    pub fn load(
48	        tokenizer_path: &str,
49	        codebook_path: &str,
50	        table_path: &str,
51	        table_size: usize,
52	        model: &str,
53	    ) -> Result<Self, String> {
54	        let tokenizer = tokenizers::Tokenizer::from_file(tokenizer_path)
55	            .map_err(|e| format!("tokenizer: {}", e))?;
56	
57	        let codebook = CodebookIndex::load(
58	            std::path::Path::new(codebook_path),
59	            table_size as u16,
60	            model.into(),
61	        )
62	        .map_err(|e| format!("codebook: {}", e))?;
63	
64	        let table_data = std::fs::read(table_path).map_err(|e| format!("table: {}", e))?;
65	
66	        if table_data.len() != table_size * table_size {
67	            return Err(format!(
68	                "table size mismatch: file {} bytes, expected {}×{}={}",
69	                table_data.len(),
70	                table_size,
71	                table_size,
72	                table_size * table_size
73	            ));
74	        }
75	
76	        let engine = ThinkingEngine::new(table_data);
77	
78	        Ok(Self {
79	            tokenizer,
80	            codebook,
81	            engine,
82	            table_size,
83	            model: model.into(),
84	        })
85	    }
86	
87	    /// Load BGE-M3 from default paths.
88	    pub fn load_bge_m3() -> Result<Self, String> {
89	        Self::load(
90	            "/tmp/bge-m3-tokenizer.json",
91	            "/tmp/codebooks/bge-m3-roles-f16/codebook_index.u16",
92	            "/tmp/codebooks/bge-m3-roles-f16/attn_q/distance_table_1024x1024.u8",
93	            1024,
94	            "bge-m3",
95	        )
96	    }
97	
98	    /// The core pipeline: text → thought.
99	    ///
100	    /// ```text
101	    /// text → tokenize → codebook lookup → perturb → think → commit
102	    /// ```
103	    pub fn think(&mut self, text: &str) -> ThoughtResult {
104	        let start = std::time::Instant::now();
105	
106	        // Tokenize
107	        let encoding = self
108	            .tokenizer
109	            .encode(text, true)
110	            .expect("tokenization failed");
111	        let token_ids = encoding.get_ids();
112	
113	        // Codebook lookup: token_id → centroid row
114	        let indices = self.codebook.lookup_many(token_ids);
115	
116	        // Count unique atoms
117	        let mut unique = indices.clone();
118	        unique.sort();
119	        unique.dedup();
120	        let unique_atoms = unique.len();
121	
122	        // Perturb + think
123	        self.engine.reset();
124	        self.engine.perturb(&indices);
125	        self.engine.think(10);
126	
127	        let bus = self.engine.commit();
128	        let entropy = self.engine.entropy();
129	        let active = self.engine.active_count(0.001);
130	
131	        ThoughtResult {
132	            bus,
133	            token_count: token_ids.len(),
134	            unique_atoms,
135	            entropy,
136	            active_count: active,
137	            think_micros: start.elapsed().as_micros() as u64,
138	        }
139	    }
140	
141	    /// Think about two texts and return both results for comparison.
142	    pub fn compare(&mut self, text_a: &str, text_b: &str) -> (ThoughtResult, ThoughtResult, u8) {
143	        let a = self.think(text_a);
144	        let b = self.think(text_b);
145	
146	        // Distance between dominant atoms in the table
147	        let idx_a = a.bus.codebook_index as usize;
148	        let idx_b = b.bus.codebook_index as usize;
149	        let dist = if idx_a < self.table_size && idx_b < self.table_size {
150	            // Read from engine's table via the stored table data
151	            // (engine doesn't expose table, recompute from the index)
152	            128u8 // placeholder — would need table access
153	        } else {
154	            128u8
155	        };
156	
157	        (a, b, dist)
158	    }
159	
160	    /// Get a reference to the underlying engine (for qualia computation).
161	    pub fn engine(&self) -> &ThinkingEngine {
162	        &self.engine
163	    }
164	
165	    /// Get the sigma floor the engine is using.
166	    pub fn floor(&self) -> u8 {
167	        self.engine.floor
168	    }
169	
170	    /// Get the tokenizer vocab size.
171	    pub fn vocab_size(&self) -> usize {
172	        self.tokenizer.get_vocab_size(true)
173	    }
174	
175	    /// Get codebook coverage stats.
176	    pub fn codebook_stats(&self) -> (usize, usize) {
177	        (self.codebook.len(), self.codebook.unique_centroids())
178	    }
179	}
180	
