1	//! `codebook` — the LE loader for the TRAINED Cam96 codebook + word codes.
2	//!
3	//! This retires the `demo()` placeholder for real use: the artifacts (the
4	//! `AdaWorldAPI/lance-graph` release `v0.1.0-cam96-data`, fetched into `data/` per its
5	//! README) were produced from real Jina-v3 96-d embeddings of the KJV Bible
6	//! vocabulary (12,543 words), k-means-256 per axis (see `probes/README.md`
7	//! § trained codebook for the held-out measurement: 96-bit ρ 0.774 vs the
8	//! 48-bit point's 0.617 on 299,882 held-out pairs).
9	//!
10	//! ## Formats (little-endian, this crate's own — no serde)
11	//!
12	//! `cam96_codebook.bin`: magic `CAM96CB1` · `u32` n_axes (12) · `u32` dim ·
13	//! `u32` n_centroids (≤256) · `f32` d_max · then `n_axes × n_centroids × dim`
14	//! `f32` centroid data in axis-major order.
15	//!
16	//! `cam96_codes.bin`: magic `CAM96WD1` · `u32` n_words · then `n_words × 12`
17	//! bytes, one [`Cam96`] per word, in vocabulary order (pair with the
18	//! frequency-ranked vocab list so `codes[id]` matches [`crate::vocab::WordId`]).
19	
20	use crate::space::{Cam96, Cam96Space};
21	
22	/// Loader error — which structural check failed.
23	#[derive(Debug, Clone, PartialEq, Eq)]
24	pub enum CodebookError {
25	    /// Wrong or missing magic bytes.
26	    BadMagic,
27	    /// Header fields inconsistent (n_axes ≠ 12, zero dim, >256 centroids).
28	    BadHeader,
29	    /// Byte length does not match the header's promised payload.
30	    Truncated,
31	}
32	
33	fn read_u32(b: &[u8], at: usize) -> Option<u32> {
34	    Some(u32::from_le_bytes(b.get(at..at + 4)?.try_into().ok()?))
35	}
36	
37	/// Parse a `CAM96CB1` codebook blob into a [`Cam96Space`].
38	///
39	/// # Errors
40	/// [`CodebookError`] naming the failed structural check; never panics on
41	/// malformed input.
42	pub fn load_cam96_space(bytes: &[u8]) -> Result<Cam96Space, CodebookError> {
43	    if bytes.get(..8) != Some(b"CAM96CB1".as_slice()) {
44	        return Err(CodebookError::BadMagic);
45	    }
46	    let n_axes = read_u32(bytes, 8).ok_or(CodebookError::Truncated)? as usize;
47	    let dim = read_u32(bytes, 12).ok_or(CodebookError::Truncated)? as usize;
48	    let n_cent = read_u32(bytes, 16).ok_or(CodebookError::Truncated)? as usize;
49	    let d_max = f32::from_le_bytes(
50	        bytes
51	            .get(20..24)
52	            .ok_or(CodebookError::Truncated)?
53	            .try_into()
54	            .map_err(|_| CodebookError::Truncated)?,
55	    );
56	    // A corrupt d_max must fail loudly here, not silently clamp to 1.0 in
57	    // `from_axis_codebooks` — an artifact loader rejects, never repairs.
58	    if n_axes != 12 || dim == 0 || n_cent == 0 || n_cent > 256 || !d_max.is_finite() || d_max <= 0.0
59	    {
60	        return Err(CodebookError::BadHeader);
61	    }
62	    let payload = &bytes[24..];
63	    let expect = n_axes * n_cent * dim * 4;
64	    if payload.len() < expect {
65	        return Err(CodebookError::Truncated);
66	    }
67	    let mut axes = Vec::with_capacity(n_axes);
68	    let mut off = 0;
69	    for _ in 0..n_axes {
70	        let mut axis = Vec::with_capacity(n_cent);
71	        for _ in 0..n_cent {
72	            let c: Vec<f32> = (0..dim)
73	                .map(|d| {
74	                    f32::from_le_bytes(payload[off + d * 4..off + d * 4 + 4].try_into().unwrap())
75	                })
76	                .collect();
77	            off += dim * 4;
78	            axis.push(c);
79	        }
80	        axes.push(axis);
81	    }
82	    Ok(Cam96Space::from_axis_codebooks(axes, d_max))
83	}
84	
85	/// Parse a `CAM96WD1` codes blob into per-word [`Cam96`] codes
86	/// (`codes[id]` in vocabulary order).
87	///
88	/// # Errors
89	/// [`CodebookError`] naming the failed structural check.
90	pub fn load_cam96_codes(bytes: &[u8]) -> Result<Vec<Cam96>, CodebookError> {
91	    if bytes.get(..8) != Some(b"CAM96WD1".as_slice()) {
92	        return Err(CodebookError::BadMagic);
93	    }
94	    let n = read_u32(bytes, 8).ok_or(CodebookError::Truncated)? as usize;
95	    let payload = &bytes[12..];
96	    if payload.len() < n * 12 {
97	        return Err(CodebookError::Truncated);
98	    }
99	    Ok((0..n)
100	        .map(|i| {
101	            let mut c = [0u8; 12];
102	            c.copy_from_slice(&payload[i * 12..i * 12 + 12]);
103	            c
104	        })
105	        .collect())
106	}
107	
