134	        // encode a vector made of axis-k centroid 2 → recovers index 2 per axis.
135	        let v: Vec<f32> = (0..12)
136	            .flat_map(|a| (0..3).map(move |d| (a + 2 + d) as f32))
137	            .collect();
138	        assert_eq!(space.encode(&v), [2u8; 12]);
139	    }
140	
141	    #[test]
142	    fn codes_round_trip_and_reject_garbage() {
143	        let mut b = Vec::new();
144	        b.extend_from_slice(b"CAM96WD1");
145	        b.extend_from_slice(&2u32.to_le_bytes());
146	        b.extend_from_slice(&[1u8; 12]);
147	        b.extend_from_slice(&[7u8; 12]);
148	        let codes = load_cam96_codes(&b).unwrap();
149	        assert_eq!(codes, vec![[1u8; 12], [7u8; 12]]);
150	        assert_eq!(load_cam96_codes(b"nope"), Err(CodebookError::BadMagic));
151	        assert!(matches!(
152	            load_cam96_space(&tiny_codebook_blob(3, 4)[..30]),
153	            Err(CodebookError::Truncated)
154	        ));
155	        // corrupt d_max (zero / negative / NaN) is BadHeader, never a silent clamp.
156	        for bad in [0.0f32, -1.0, f32::NAN] {
157	            let mut blob = tiny_codebook_blob(3, 4);
158	            blob[20..24].copy_from_slice(&bad.to_le_bytes());
159	            assert!(matches!(
160	                load_cam96_space(&blob),
161	                Err(CodebookError::BadHeader)
162	            ));
163	        }
164	    }
