1	//! `belief` — the V0 falsifying slice of the dialectic engine
2	//! (`.claude/plans/dialectic-engine-v1.md` §4): a Belief-carrying arena where
3	//! **revision merges truth in place on the unique statement** (triple-keyed
4	//! dedup — the termination proof of `reason.rs` preserved verbatim) under a
5	//! **fixed-width observation-source stamp** with the disjointness guard the
6	//! shipped `nars_revision` lacks.
7	//!
8	//! Synthesis decisions embodied (S2, S3, S4 of the plan):
9	//! - **S2:** a statement exists ONCE; revision updates `(truth, stamp)` in
10	//!   place at its EXISTING rung; only genuinely-new statements get
11	//!   `max(premise rungs)+1`. Closure-internal duplicates resolve by CHOICE
12	//!   (higher expectation), never a stamped duplicate entry.
13	//! - **S3:** `Copula { Inh, Sim, Impl, Rel }` — **only `Inh` and `Sim`
14	//!   auto-transit**; `Rel` (FSM verbs) NEVER freely composes. This fixes the
15	//!   latent unsoundness of the blanket same-predicate closure
16	//!   ("dog bit man" + "man bit sandwich" ⊬ "dog bit sandwich").
17	//! - **S4:** `Stamp(u64)` — a bitset over a bounded horizon of OBSERVATION
18	//!   sources (never derivation ancestry: unbounded, serializing). Disjoint →
19	//!   NARS revision (evidence pooling, synthesis confidence above both inputs,
20	//!   contradiction depth |f₁−f₂| preserved). Overlap → CHOICE, no double count.
21	//!
22	//! NARS is treated as LOGIC here (`E-NARS-IS-LOGIC-...-1`): statements compose
23	//! by shared terms; truth moves only by truth functions. No fingerprints.
24	
25	use lance_graph_contract::exploration::NarsTruth;
26	use std::collections::HashMap;
27	
28	/// Fixed-width evidential stamp: bit *i* = observation source *i* (bounded
29	/// horizon of 64 sources; sources beyond the horizon fold by modulo, which is
30	/// CONSERVATIVE — folding can only create false overlap, never false
31	/// disjointness, so the no-double-count guarantee survives the bound).
32	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
33	pub struct Stamp(pub u64);
34	
35	impl Stamp {
36	    /// The stamp of a single observation source.
37	    #[must_use]
38	    pub fn source(id: u32) -> Self {
39	        Stamp(1u64 << (id % 64))
40	    }
41	    /// Two stamps share no evidence.
42	    #[must_use]
43	    pub fn disjoint(self, other: Self) -> bool {
44	        self.0 & other.0 == 0
45	    }
46	    /// Pooled evidence base.
47	    #[must_use]
48	    pub fn union(self, other: Self) -> Self {
49	        Stamp(self.0 | other.0)
50	    }
51	}
52	
53	/// The copula of a concept-level statement (S3). `Rel` carries an arbitrary
54	/// relational term (an FSM verb id) — stored, queryable, NEVER transitive.
55	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
56	pub enum Copula {
57	    /// Inheritance `→` (is_a). Transitive: composes by shared middle term.
58	    Inh,
59	    /// Similarity `↔`. Transitive (resemblance chains, weaker).
60	    Sim,
61	    /// Implication `⇒` (reasoned causality). NOT auto-transitive in V0 —
62	    /// causal chaining goes through explicit tactics (V1), never blanket closure.
63	    Impl,
64	    /// An arbitrary relational term (verb). NEVER transits.
65	    Rel(u16),
66	}
67	
68	impl Copula {
69	    /// May the blanket transitive closure compose two statements of this copula?
70	    #[must_use]
71	    pub fn transits(self) -> bool {
72	        matches!(self, Copula::Inh | Copula::Sim)
73	    }
74	}
75	
76	/// A concept-level statement: subject –copula– predicate (terms are interned
77	/// dense concept ids; `NodeGuid` remains the addressable identity outside the
78	/// reasoning index — never a 16-byte pivot key).
79	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
80	pub struct CStmt {
81	    /// Subject concept id.
82	    pub s: u16,
83	    /// The copula (carries the verb id when `Rel`).
84	    pub cop: Copula,
85	    /// Predicate concept id.
86	    pub p: u16,
87	}
