89	/// One belief: a unique statement with its NARS truth, evidential stamp,
90	/// Tarski rung, and premise pointers (empty = observed).
91	#[derive(Debug, Clone)]
92	pub struct Belief {
93	    /// The statement (UNIQUE in the arena — S2).
94	    pub stmt: CStmt,
95	    /// Current NARS truth (moves only via revision/CHOICE).
96	    pub truth: NarsTruth,
97	    /// Evidential base (bounded source bitset — S4).
98	    pub stamp: Stamp,
99	    /// Tarski rung: 0 observed; derived = max(premise rungs)+1, fixed at
100	    /// creation — revision does NOT change it (S2 / rung-inflation fix).
101	    pub rung: u32,
102	    /// Arena indices of premises (derived beliefs only; always earlier).
103	    pub premises: Vec<u32>,
104	    /// Preserved dialectic depth: max |f₁−f₂| seen across revisions of this
105	    /// statement (the contradiction is committed, not erased).
106	    pub contradiction: f32,
107	}
108	
109	/// Outcome of offering evidence to the arena (observe/revise path).
110	#[derive(Debug, Clone, Copy, PartialEq)]
111	pub enum ReviseOutcome {
112	    /// New statement admitted (was absent).
113	    Admitted { id: u32 },
114	    /// Same statement, DISJOINT stamps → NARS revision pooled the evidence in
115	    /// place; `synthesis_c` is the pooled confidence (≥ both inputs),
116	    /// `depth` the |f₁−f₂| dialectic gap that was preserved.
117	    Revised {
118	        id: u32,
119	        synthesis_c: f32,
120	        depth: f32,
121	    },
122	    /// Same statement, OVERLAPPING stamps → CHOICE kept the higher-confidence
123	    /// truth; no evidence was double-counted.
124	    Chosen { id: u32, kept_existing: bool },
125	}
126	
127	/// The dialectic belief arena: triple-keyed (statement-keyed) — a statement
128	/// exists exactly once, so the `reason.rs` finite-closure termination argument
129	/// applies verbatim (the derivable set ⊆ terms × copulas × terms, finite; each
130	/// statement admitted at most once).
131	#[derive(Debug, Default)]
132	pub struct BeliefArena {
133	    entries: Vec<Belief>,
134	    index: HashMap<CStmt, u32>,
135	    /// Closure passes run by the last `close_transitive` call.
136	    pub passes: u32,
137	    /// Whether the last closure reached a true fixed point.
138	    pub reached_fixed_point: bool,
139	}
140	
141	impl BeliefArena {
142	    /// Empty arena.
143	    #[must_use]
144	    pub fn new() -> Self {
145	        Self::default()
146	    }
147	
148	    /// All beliefs, in admission order.
149	    #[must_use]
150	    pub fn entries(&self) -> &[Belief] {
151	        &self.entries
152	    }
153	
154	    /// Look up a statement's belief.
155	    #[must_use]
156	    pub fn get(&self, stmt: CStmt) -> Option<&Belief> {
157	        self.index.get(&stmt).map(|&i| &self.entries[i as usize])
158	    }
159	
160	    /// Offer evidence for a statement (rung 0 observation path). Admits it if
161	    /// absent; otherwise routes through the S4 guard: disjoint → revision
162	    /// in place; overlap → CHOICE. The arena NEVER grows a second entry for an
163	    /// existing statement — the termination invariant.
164	    pub fn observe(&mut self, stmt: CStmt, truth: NarsTruth, stamp: Stamp) -> ReviseOutcome {
165	        match self.index.get(&stmt) {
166	            None => {
167	                let id = self.entries.len() as u32;
168	                self.entries.push(Belief {
169	                    stmt,
170	                    truth,
171	                    stamp,
172	                    rung: 0,
173	                    premises: Vec::new(),
174	                    contradiction: 0.0,
175	                });
176	                self.index.insert(stmt, id);
177	                ReviseOutcome::Admitted { id }
178	            }
179	            Some(&id) => self.revise_at(id, truth, stamp),
180	        }
181	    }
182	
183	    /// The S4 revision guard on an existing belief. Disjoint stamps → NARS
184	    /// evidence pooling (`NarsTruth::revision`) + stamp union + preserved
185	    /// |f₁−f₂| depth, IN PLACE (rung untouched). Overlapping stamps → CHOICE:
186	    /// keep the higher-confidence truth, count nothing twice.
187	    pub fn revise_at(&mut self, id: u32, new: NarsTruth, stamp: Stamp) -> ReviseOutcome {
188	        let b = &mut self.entries[id as usize];
189	        if b.stamp.disjoint(stamp) {
190	            let depth = (b.truth.frequency - new.frequency).abs();
191	            b.contradiction = b.contradiction.max(depth);
192	            b.truth = b.truth.revision(&new);
193	            b.stamp = b.stamp.union(stamp);
194	            ReviseOutcome::Revised {
195	                id,
196	                synthesis_c: b.truth.confidence,
197	                depth,
198	            }
199	        } else {
200	            let kept_existing = b.truth.confidence >= new.confidence;
201	            if !kept_existing {
202	                b.truth = new;
203	                b.stamp = b.stamp.union(stamp);
204	            }
205	            ReviseOutcome::Chosen { id, kept_existing }
206	        }
207	    }
208	
209	    /// Copula-gated transitive closure (S3): compose `{A cop B, B cop C} ⊢
210	    /// A cop C` ONLY for `cop.transits()` (Inh, Sim), with NARS deduction
211	    /// truth `f=f₁f₂, c=f₁f₂c₁c₂` computed per ordered premise pair (truth is
212	    /// NOT an mxm quantity — S1; this scalar path IS the second-pass form at
213	    /// V0 scale). A statement exists exactly once (S2); every derivation of
214	    /// that statement — including multiple paths to the same conclusion (a weak
215	    /// A→B→C vs a strong A→D→C) — is resolved by **CHOICE on `expectation()`**,
216	    /// NOT by which path was walked first. Concretely, per pass:
217	    /// - all derivations are collected keyed by the derived statement, keeping
218	    ///   the maximum-`expectation()` candidate (order-independent — the Codex
219	    ///   P2 fix; the earlier `continue`-on-duplicate made stored truth depend
220	    ///   on iteration order);
221	    /// - an ABSENT statement is admitted rung-stamped `max(premise rungs)+1`;
222	    /// - an OBSERVATION-GROUNDED statement (non-empty stamp — whether observed
223	    ///   before it was ever derived, rung 0, or derived-then-observed, rung ≥ 1)
224	    ///   is ground and a pure derivation never overrides it;
225	    /// - a PURE-DERIVED statement (empty stamp) is updated only when the winning
226	    ///   derivation's `expectation()` strictly exceeds the stored one (`EPS`).
227	    ///
228	    /// Termination: each stored expectation only ever increases and is bounded
229	    /// (deduction confidence is a product of confidences < 1, so a longer path
230	    /// can never exceed a shorter one), so the number of `changed` passes is
231	    /// finite — the `reason.rs` finiteness argument holds and the closure
232	    /// reaches a true fixed point (`max_passes` is only a backstop).
233	    pub fn close_transitive(&mut self, max_passes: u32) {
234	        self.passes = 0;
235	        self.reached_fixed_point = false;
236	        // A CHOICE update fires only on a MEANINGFUL expectation gain, so float
237	        // churn cannot re-trigger passes indefinitely.
238	        const EPS: f32 = 1e-6;
239	        while self.passes < max_passes {
240	            self.passes += 1;
241	            // Pivot: (subject, copula) → entry ids, over the CURRENT arena.
242	            let mut by_sc: HashMap<(u16, Copula), Vec<u32>> = HashMap::new();
243	            for (i, b) in self.entries.iter().enumerate() {
244	                if b.stmt.cop.transits() {
245	                    by_sc
246	                        .entry((b.stmt.s, b.stmt.cop))
247	                        .or_default()
248	                        .push(i as u32);
249	                }
250	            }
251	            // Collect EVERY derivation this pass, keyed by the derived
252	            // statement, keeping the maximum-`expectation()` candidate. Two
253	            // paths to the same conclusion no longer race on insertion order.
254	            let mut derived: HashMap<CStmt, (NarsTruth, u32, [u32; 2])> = HashMap::new();
255	            for i in 0..self.entries.len() {
256	                let (a, cop, b_term, t1, r1) = {
257	                    let e = &self.entries[i];
258	                    (e.stmt.s, e.stmt.cop, e.stmt.p, e.truth, e.rung)
259	                };
260	                if !cop.transits() {
261	                    continue;
262	                }
263	                let Some(js) = by_sc.get(&(b_term, cop)) else {
264	                    continue;
265	                };
266	                for &j in js {
267	                    let (c_term, t2, r2) = {
268	                        let e = &self.entries[j as usize];
269	                        (e.stmt.p, e.truth, e.rung)
270	                    };
271	                    let stmt = CStmt {
272	                        s: a,
273	                        cop,
274	                        p: c_term,
275	                    };
276	                    // NARS deduction truth, per ordered pair (S1 second-pass form).
277	                    let f = t1.frequency * t2.frequency;
278	                    let c = f * t1.confidence * t2.confidence;
279	                    let truth = NarsTruth::new(f, c);
280	                    let cand = (truth, r1.max(r2) + 1, [i as u32, j]);
281	                    match derived.get(&stmt) {
282	                        Some((best, ..)) if best.expectation() >= truth.expectation() => {}
283	                        _ => {
284	                            derived.insert(stmt, cand);
285	                        }
286	                    }
287	                }
288	            }
289	            // Apply each winning derivation through CHOICE against the arena.
290	            // Absent → admit; observation-grounded → untouched; pure derivation →
291	            // update only on a strict expectation gain. Order-independent: at
292	            // most one candidate per statement, and admit/gain-update never
293	            // interfere across distinct statements.
294	            let mut changed = false;
295	            for (stmt, (truth, rung, premises)) in derived {
296	                match self.index.get(&stmt) {
297	                    Some(&id) => {
298	                        let e = &mut self.entries[id as usize];
299	                        // Any belief carrying observation evidence — a non-empty
300	                        // stamp — is GROUND: a pure derivation never overwrites
301	                        // it. This catches BOTH a purely-observed belief (rung 0)
302	                        // AND a derived-then-observed one (rung ≥ 1, but its stamp
303	                        // was unioned in by `revise_at` — a derived belief's zero
304	                        // stamp is disjoint from every observation, so observing
305	                        // it always pools). The `rung == 0` guard missed the
306	                        // latter and would drop the observed evidence.
307	                        if e.stamp != Stamp::default() {
308	                            continue; // observation dominates a derivation
309	                        }
310	                        if truth.expectation() > e.truth.expectation() + EPS {
311	                            e.truth = truth;
312	                            e.rung = rung;
313	                            e.premises = premises.to_vec();
314	                            changed = true;
315	                        }
316	                    }
317	                    None => {
318	                        let id = self.entries.len() as u32;
319	                        self.entries.push(Belief {
320	                            stmt,
321	                            truth,
322	                            stamp: Stamp::default(), // derived: no observation sources of its own
323	                            rung,
324	                            premises: premises.to_vec(),
325	                            contradiction: 0.0,
326	                        });
327	                        self.index.insert(stmt, id);
328	                        changed = true;
329	                    }
330	                }
331	            }
332	            if !changed {
333	                self.reached_fixed_point = true;
334	                return;
335	            }
336	        }
337	    }
338	}
