498	        assert_eq!(d.rung, 1);
499	        assert_eq!(d.premises.len(), 2, "premise pointers carried");
500	    }
501	
502	    /// S2 rung semantics: revision is an in-place truth UPDATE — the rung does
503	    /// not move (no rung inflation; one statement, one rung).
504	    #[test]
505	    fn revision_keeps_rung_in_place() {
506	        let mut arena = BeliefArena::new();
507	        arena.observe(inh(1, 2), NarsTruth::new(0.9, 0.8), Stamp::source(0));
508	        arena.observe(inh(2, 3), NarsTruth::new(0.9, 0.8), Stamp::source(1));
509	        arena.close_transitive(16);
510	        let derived = inh(1, 3);
511	        assert_eq!(arena.get(derived).unwrap().rung, 1);
512	        // Independent observation of the derived statement revises it in place…
513	        let out = arena.observe(derived, NarsTruth::new(0.7, 0.6), Stamp::source(9));
514	        assert!(matches!(out, ReviseOutcome::Revised { .. }));
515	        // …at its EXISTING rung.
516	        assert_eq!(
517	            arena.get(derived).unwrap().rung,
518	            1,
519	            "rung fixed at creation"
520	        );
521	    }
522	
523	    /// Close a two-path arena (weak A→B→C vs strong A→D→C) in a chosen
524	    /// insertion order and return the derived truth of A→C. A=0, B=1, C=2, D=3.
525	    fn close_two_paths_to_ac(strong_first: bool) -> NarsTruth {
526	        let weak: [(CStmt, NarsTruth); 2] = [
527	            (inh(0, 1), NarsTruth::new(0.6, 0.5)), // A→B (weak)
528	            (inh(1, 2), NarsTruth::new(0.6, 0.5)), // B→C (weak)
529	        ];
530	        let strong: [(CStmt, NarsTruth); 2] = [
531	            (inh(0, 3), NarsTruth::new(0.95, 0.9)), // A→D (strong)
532	            (inh(3, 2), NarsTruth::new(0.95, 0.9)), // D→C (strong)
533	        ];
534	        let order: [&[(CStmt, NarsTruth)]; 2] = if strong_first {
535	            [&strong, &weak]
536	        } else {
537	            [&weak, &strong]
538	        };
539	        let mut arena = BeliefArena::new();
540	        let mut src = 0u32;
541	        for group in order {
542	            for &(stmt, truth) in group {
543	                arena.observe(stmt, truth, Stamp::source(src));
544	                src += 1;
545	            }
546	        }
547	        arena.close_transitive(64);
548	        assert!(arena.reached_fixed_point, "closure must terminate");
549	        arena.get(inh(0, 2)).expect("A→C must derive").truth
550	    }
551	
552	    /// CODEX P2 REGRESSION (`close_transitive` CHOICE-for-duplicates fix): when
553	    /// two paths reach the same conclusion (a weak A→B→C and a strong A→D→C),
554	    /// the stored truth of A→C is decided by CHOICE on `expectation()` and is
555	    /// therefore INDEPENDENT of which path is walked first. Before the fix the
556	    /// first-encountered derivation was `continue`-skipped and permanently won,
557	    /// making stored truth insertion-order-dependent (violating S2).
558	    #[test]
559	    fn transitive_duplicate_resolves_by_choice_not_insertion_order() {
560	        // Deduction truth of the STRONG path A→C: f=0.95², c=f·0.9² — the higher
561	        // expectation, so CHOICE must keep it in BOTH orderings.
562	        let want_f = 0.95f32 * 0.95;
563	        let want_c = want_f * 0.9 * 0.9;
564	
565	        let strong_first = close_two_paths_to_ac(true);
566	        let weak_first = close_two_paths_to_ac(false);
567	
568	        for (label, t) in [("strong-first", strong_first), ("weak-first", weak_first)] {
569	            assert!(
570	                (t.frequency - want_f).abs() < 1e-6 && (t.confidence - want_c).abs() < 1e-6,
571	                "{label}: CHOICE must keep the strong-path truth (f={want_f}, c={want_c}), \
572	                 got f={}, c={}",
573	                t.frequency,
574	                t.confidence,
575	            );
576	        }
577	        // The two orderings agree exactly — the order-independence Codex asked for.
578	        assert!((strong_first.frequency - weak_first.frequency).abs() < 1e-9);
579	        assert!((strong_first.confidence - weak_first.confidence).abs() < 1e-9);
580	    }
581	
582	    /// CODEX P2 REGRESSION (the second, subtler one): a belief that is DERIVED
583	    /// first and OBSERVED later keeps its rung (≥ 1) but now carries real
584	    /// observation evidence (its stamp was unioned in by revision). A later
585	    /// closure that finds a higher-expectation pure derivation must NOT
586	    /// overwrite it — the `rung == 0` guard missed this; the stamp guard catches
587	    /// it. Scenario: derive A→C from weak A→B→C, observe A→C, add strong
588	    /// A→D→C, re-close — the observed/revised truth must survive intact.
589	    #[test]
590	    fn closure_does_not_overwrite_a_derived_then_observed_belief() {
591	        let mut arena = BeliefArena::new();
592	        // 1) Derive A→C weakly from A→B→C (rung 1, empty stamp).
593	        arena.observe(inh(0, 1), NarsTruth::new(0.6, 0.5), Stamp::source(0));
594	        arena.observe(inh(1, 2), NarsTruth::new(0.6, 0.5), Stamp::source(1));
595	        arena.close_transitive(64);
596	        assert_eq!(arena.get(inh(0, 2)).unwrap().rung, 1, "A→C derived");
597	        // 2) Observe A→C directly (disjoint source): revision pools evidence in
598	        //    place at rung 1 — the belief now carries a non-empty stamp. Chosen
599	        //    so its expectation stays BELOW the strong path's, proving the guard
600	        //    (not the expectation test) is what protects it.
601	        let out = arena.observe(inh(0, 2), NarsTruth::new(0.55, 0.9), Stamp::source(2));
602	        assert!(
603	            matches!(out, ReviseOutcome::Revised { .. }),
604	            "disjoint → revision (derived belief's zero stamp is disjoint from any source)"
605	        );
606	        let observed = arena.get(inh(0, 2)).unwrap().truth;
607	        // 3) Add a STRONGER path A→D→C (deduction expectation ≈ 0.79, above the
608	        //    revised A→C) and re-close. The pre-fix code would overwrite A→C with
609	        //    the pure derivation, dropping the observation.
610	        arena.observe(inh(0, 3), NarsTruth::new(0.95, 0.9), Stamp::source(3));
611	        arena.observe(inh(3, 2), NarsTruth::new(0.95, 0.9), Stamp::source(4));
612	        arena.close_transitive(64);
613	        let after = arena.get(inh(0, 2)).unwrap().truth;
614	        assert_eq!(
615	            (after.frequency, after.confidence),
616	            (observed.frequency, observed.confidence),
617	            "closure must not overwrite an observation-grounded belief with a pure derivation"
618	        );
619	        // It did NOT become the pure strong derivation (f = 0.95²) — observation survived.
620	        assert!(
621	            (after.frequency - 0.95 * 0.95).abs() > 1e-2,
622	            "observed evidence survived, not replaced by the strong derivation"
623	        );
624	    }
625	}
