1	//! `ancestry` — the family radix-trie codebook: **ancestry lives in the KEY,
2	//! never in derived triples.**
3	//!
4	//! The operator ruling that reshaped `D-SRS-2` (`self-reasoning-substrate-v1`):
5	//! ancestry is classic **HHTL family identity** — Distinguished-Name-like
6	//! chains, a radix-trie codebook ontology. A node's DN (its root-path) IS its
7	//! lineage, so `is_ancestor_of(A, Z)` = *A's DN is a strict prefix of Z's DN* —
8	//! radix-trie containment, the same law as the 4⁴ centroid-hierarchy canon
9	//! (`is_ancestor_of` = centroid-tree containment) and the `part_of:is_a` rails.
10	//!
11	//! This is the amortization that retires the `D-SRS-1` O(N²) finding: a
12	//! materialized transitive closure stores **every ancestor pair**; the trie
13	//! stores **one parent pointer per entity** and answers any ancestor query by a
14	//! prefix read. The closure was the wrong carrier, not merely an unbounded one.
15	//!
16	//! ## Contract (pre-registered in the plan, G-SRS2 trie contract)
17	//!
18	//! - Each covered entity has ONE parent — the FIRST parent edge seen wins
19	//!   (primary); later conflicting parent edges are counted as
20	//!   [`multi_parent_residue`](FamilyTrie::multi_parent_residue) and are NOT in
21	//!   the forest (they route to the fabric / Escalate, never silently dropped
22	//!   into the trie).
23	//! - Entities on a parent-cycle cannot reach a root; they are UNCOVERED
24	//!   ([`cycle_residue`](FamilyTrie::cycle_residue)) — the trie never lies about
25	//!   a lineage it cannot ground.
26	//! - `is_ancestor_of` is exact on the covered forest and `false` for anything
27	//!   uncovered.
28	
29	use std::collections::HashMap;
30	
31	/// The family radix-trie: one primary parent pointer per covered entity, DN =
32	/// the root-path, ancestry = DN prefix containment.
33	#[derive(Debug, Clone)]
34	pub struct FamilyTrie {
35	    /// child → primary parent (first-wins), for every child that appeared.
36	    parent: HashMap<u16, u16>,
37	    /// entity → depth (root = 0), for COVERED entities only.
38	    depth: HashMap<u16, u32>,
39	    /// Parent edges rejected because the child already had a primary parent.
40	    multi_parent: usize,
41	    /// Entities excluded because their parent walk loops (never reaches a root).
42	    on_cycle: usize,
43	}
44	
45	impl FamilyTrie {
46	    /// Build the trie from `(parent, child)` edges (for an SPO triple
47	    /// `(A, begat, B)`, `A` is the parent and `B` the child).
48	    ///
49	    /// First parent wins; later parent edges for the same child count as
50	    /// multi-parent residue. After the parent map is fixed, every entity is
51	    /// walked to a root; entities whose walk revisits a node (a parent cycle)
52	    /// are uncovered cycle-residue.
53	    #[must_use]
54	    pub fn build(edges: &[(u16, u16)]) -> Self {
55	        let mut parent: HashMap<u16, u16> = HashMap::new();
56	        let mut multi_parent = 0usize;
57	        for &(p, c) in edges {
58	            if p == c {
59	                multi_parent += 1; // a self-parent can never ground a lineage
60	                continue;
61	            }
62	            match parent.entry(c) {
63	                std::collections::hash_map::Entry::Occupied(_) => multi_parent += 1,
64	                std::collections::hash_map::Entry::Vacant(v) => {
65	                    v.insert(p);
66	                }
67	            }
68	        }
69	
70	        // Cover: walk each entity to a root, memoizing depth. A walk that
71	        // revisits a node in progress is a cycle — everyone on it is uncovered.
72	        let mut depth: HashMap<u16, u32> = HashMap::new();
73	        let mut on_cycle_set: HashMap<u16, bool> = HashMap::new(); // true = cyclic
74	        let mut entities: Vec<u16> = parent.keys().copied().collect();
75	        entities.extend(parent.values().copied());
76	        entities.sort_unstable();
77	        entities.dedup();
78	
79	        for &e in &entities {
80	            if depth.contains_key(&e) || on_cycle_set.contains_key(&e) {
81	                continue;
82	            }
83	            // Walk up, recording the chain until a known node or a root.
84	            let mut chain: Vec<u16> = Vec::new();
85	            let mut chain_pos: HashMap<u16, usize> = HashMap::new();
86	            let mut cur = e;
87	            let outcome: Result<u32, usize> = loop {
88	                if let Some(&d) = depth.get(&cur) {
89	                    break Ok(d); // reached an already-covered node
90	                }
91	                if on_cycle_set.get(&cur) == Some(&true) {
92	                    break Err(0); // reached a known-cyclic node — whole chain sinks
93	                }
94	                if let Some(&pos) = chain_pos.get(&cur) {
95	                    break Err(pos); // new cycle discovered within this walk
96	                }
97	                chain_pos.insert(cur, chain.len());
98	                chain.push(cur);
99	                match parent.get(&cur) {
100	                    Some(&p) => cur = p,
101	                    None => break Ok(u32::MAX), // root sentinel (depth -1 conceptually)
102	                }
103	            };
104	            match outcome {
105	                Ok(base) => {
106	                    // `chain` was built walking UP (leaf-ward first), so its
107	                    // LAST element is root-most. Assign depths in reverse:
108	                    // root-most gets the smallest depth (0 at a true root, or
109	                    // one below an already-covered node at depth `base`).
110	                    let start = if base == u32::MAX { 0 } else { base + 1 };
111	                    for (i, &n) in chain.iter().rev().enumerate() {
112	                        depth.insert(n, start + i as u32);
113	                    }
114	                }
115	                Err(_) => {
116	                    for &n in &chain {
117	                        on_cycle_set.insert(n, true);
118	                    }
119	                }
120	            }
121	        }
122	
123	        let on_cycle = on_cycle_set.len();
124	        Self {
125	            parent,
126	            depth,
127	            multi_parent,
128	            on_cycle,
129	        }
130	    }
131	
132	    /// Number of covered entities (each stores exactly one parent pointer or is
133	    /// a root) — the trie's total storage in the amortization gate.
134	    #[must_use]
135	    pub fn covered(&self) -> usize {
136	        self.depth.len()
137	    }
138	
139	    /// Parent edges rejected by first-wins (routed to fabric/Escalate).
140	    #[must_use]
141	    pub fn multi_parent_residue(&self) -> usize {
142	        self.multi_parent
143	    }
144	
145	    /// Entities uncovered because their lineage loops.
146	    #[must_use]
147	    pub fn cycle_residue(&self) -> usize {
148	        self.on_cycle
149	    }
150	
151	    /// The DN (root-path, root first) of a covered entity.
152	    #[must_use]
153	    pub fn dn(&self, e: u16) -> Option<Vec<u16>> {
154	        self.depth.get(&e)?;
155	        let mut path = vec![e];
156	        let mut cur = e;
157	        while let Some(&p) = self.parent.get(&cur) {
158	            if !self.depth.contains_key(&p) {
159	                break;
160	            }
161	            path.push(p);
162	            cur = p;
163	        }
164	        path.reverse();
165	        Some(path)
166	    }
167	
168	    /// `is_ancestor_of(A, Z)` — A's DN is a STRICT prefix of Z's DN, answered by
169	    /// walking Z up exactly `depth(Z) − depth(A)` steps (reading the DN tail);
170	    /// the O(1) form is the nibble-packed HHTL key compare of the same path.
171	    #[must_use]
172	    pub fn is_ancestor_of(&self, a: u16, z: u16) -> bool {
173	        let (Some(&da), Some(&dz)) = (self.depth.get(&a), self.depth.get(&z)) else {
174	            return false;
175	        };
176	        if da >= dz {
177	            return false;
178	        }
179	        let mut cur = z;
180	        for _ in 0..(dz - da) {
181	            match self.parent.get(&cur) {
182	                Some(&p) => cur = p,
183	                None => return false,
184	            }
185	        }
186	        cur == a
187	    }
188	
189	    /// The NUMBER of ancestor pairs the covered forest implies (`Σ depth(v)`) —
190	    /// the amortization numerator, computed without materializing the set.
191	    #[must_use]
192	    pub fn pair_count(&self) -> usize {
193	        self.depth.values().map(|&d| d as usize).sum()
194	    }
195	
196	    /// Every ancestor pair `(ancestor, descendant)` the covered forest implies —
197	    /// the set the G-SRS2-a falsifier compares against the materialized closure.
198	    /// Size = Σ depth(v).
199	    #[must_use]
200	    pub fn ancestor_pairs(&self) -> std::collections::HashSet<(u16, u16)> {
201	        let mut out = std::collections::HashSet::new();
202	        for &e in self.depth.keys() {
203	            let mut cur = e;
204	            while let Some(&p) = self.parent.get(&cur) {
205	                if !self.depth.contains_key(&p) {
206	                    break;
207	                }
208	                out.insert((p, e));
209	                cur = p;
210	            }
211	        }
212	        out
213	    }
214	
215	    /// The covered forest's edges `(parent, child)` — exactly what the trie
216	    /// represents (residue excluded). The falsifier closes THESE edges.
217	    #[must_use]
218	    pub fn forest_edges(&self) -> Vec<(u16, u16)> {
219	        self.depth
220	            .keys()
221	            .filter_map(|&c| {
222	                let &p = self.parent.get(&c)?;
223	                self.depth.contains_key(&p).then_some((p, c))
224	            })
225	            .collect()
226	    }
227	
228	    /// Maximum DN depth over covered entities (root = 0).
229	    #[must_use]
230	    pub fn max_depth(&self) -> u32 {
231	        self.depth.values().copied().max().unwrap_or(0)
232	    }
233	
234	    /// The HHTL-packable share: covered entities whose depth ≤ 12 (the native
235	    /// 3×4-nibble path) AND whose every path node has ≤ 16 children in the
236	    /// forest (`FAN_OUT = 16`). Deeper/wider lineages are the hierarchy's
237	    /// registry-resolve + ref-escape job (canon), not a trie failure.
238	    #[must_use]
239	    pub fn hhtl_packable(&self) -> usize {
240	        // children count per covered parent.
241	        let mut fan: HashMap<u16, u32> = HashMap::new();
242	        for (p, _) in self.forest_edges() {
243	            *fan.entry(p).or_insert(0) += 1;
244	        }
245	        self.depth
246	            .iter()
247	            .filter(|&(&e, &d)| {
248	                if d > 12 {
249	                    return false;
250	                }
251	                // every ancestor on the path (and the entity's own parent hop)
252	                // must have fan-out ≤ 16.
253	                let mut cur = e;
254	                while let Some(&p) = self.parent.get(&cur) {
255	                    if !self.depth.contains_key(&p) {
256	                        break;
257	                    }
258	                    if fan.get(&p).copied().unwrap_or(0) > 16 {
259	                        return false;
260	                    }
261	                    cur = p;
262	                }
263	                true
264	            })
265	            .count()
266	    }
267	}
