325	        let t = FamilyTrie::build(&[(1, 1), (1, 2)]);
326	        assert_eq!(t.multi_parent_residue(), 1);
327	        assert!(t.is_ancestor_of(1, 2));
328	    }
329	
330	    /// THE mini-falsifier (G-SRS2-a in unit form): on a branching forest, the
331	    /// trie's implied ancestor pairs EQUAL the uncapped transitive closure of
332	    /// the same forest edges (base ∪ derived), as sets, both directions.
333	    #[test]
334	    fn trie_pairs_equal_uncapped_closure_exactly() {
335	        // Forest: 1→{2,3}, 2→{4,5}, 5→6; second tree 10→11.
336	        let edges = [(1, 2), (1, 3), (2, 4), (2, 5), (5, 6), (10, 11)];
337	        let t = FamilyTrie::build(&edges);
338	        assert_eq!(t.covered(), 8);
339	
340	        let p = 42u16;
341	        let base: Vec<Spo> = t
342	            .forest_edges()
343	            .iter()
344	            .map(|&(a, c)| Spo::new(a, p, c))
345	            .collect();
346	        let arena = DerivationArena::derive_transitive(&base);
347	        let g = arena.gate();
348	        assert!(g.passed(), "forest closure terminates soundly: {g:?}");
349	
350	        let closure: std::collections::HashSet<(u16, u16)> = arena
351	            .entries()
352	            .iter()
353	            .map(|d| (d.triple.subject, d.triple.object))
354	            .collect();
355	        assert_eq!(
356	            t.ancestor_pairs(),
357	            closure,
358	            "trie prefix-ancestry must equal the materialized closure EXACTLY"
359	        );
360	    }
361	
362	    /// `is_ancestor_of` agrees EXACTLY with `ancestor_pairs` membership over a
363	    /// branching forest (and is strict + antisymmetric) — the operational-API
364	    /// pin behind the D-SRS-2 gate.
365	    #[test]
366	    fn is_ancestor_of_agrees_with_ancestor_pairs() {
367	        let edges = [(1, 2), (1, 3), (2, 4), (2, 5), (5, 6), (10, 11)];
368	        let t = FamilyTrie::build(&edges);
369	        let pairs = t.ancestor_pairs();
370	        let covered: Vec<u16> = (0..=11).filter(|&e| t.dn(e).is_some()).collect();
371	        for &a in &covered {
372	            for &z in &covered {
373	                let via_walk = t.is_ancestor_of(a, z);
374	                let via_set = pairs.contains(&(a, z));
375	                assert_eq!(via_walk, via_set, "disagreement on ({a},{z})");
376	                if a == z {
377	                    assert!(!via_walk, "strictness: no self-ancestry");
378	                }
379	                if via_walk {
380	                    assert!(!t.is_ancestor_of(z, a), "antisymmetry on ({a},{z})");
381	                }
382	            }
383	        }
384	        assert_eq!(t.pair_count(), pairs.len());
385	    }
386	
387	    /// Star (one root, many children): depth-1 trie, pairs == edges — the
388	    /// shape where relocation buys nothing (the detector routes it to
389	    /// EdgeTable; the trie still answers correctly).
390	    #[test]
391	    fn star_is_flat_amortization() {
392	        let edges: Vec<(u16, u16)> = (1..=10).map(|c| (0, c)).collect();
393	        let t = FamilyTrie::build(&edges);
394	        assert_eq!(t.ancestor_pairs().len(), 10); // == edges: ratio 10/11 < 2
395	        assert_eq!(t.max_depth(), 1);
396	    }
397	
398	    /// HHTL packability: depth ≤ 12 and fan-out ≤ 16 pack; a 17-child hub or a
399	    /// 13-deep line does not.
400	    #[test]
401	    fn hhtl_packable_respects_depth_and_fanout() {
402	        // 13-deep chain 0→1→…→13: entities at depth ≤ 12 pack, depth 13 not.
403	        let chain: Vec<(u16, u16)> = (0..13).map(|k| (k, k + 1)).collect();
404	        let t = FamilyTrie::build(&chain);
405	        assert_eq!(t.covered(), 14);
406	        assert_eq!(t.hhtl_packable(), 13); // depths 0..=12 pack; depth 13 does not
407	
408	        // A 17-child hub: the children fail the fan-out bound, the root packs.
409	        let hub: Vec<(u16, u16)> = (1..=17).map(|c| (0, c)).collect();
410	        let t2 = FamilyTrie::build(&hub);
411	        assert_eq!(t2.hhtl_packable(), 1); // only the root
412	    }
413	}
