88	/// One corpus under test — carried as the document layer's own IR, not as a
89	/// bag of strings this crate invented a span numbering for.
90	struct Corpus {
91	    name: &'static str,
92	    /// The ORIGINAL bytes, whose sha256 is the document identity.
93	    source: Vec<u8>,
