98	/// Build a `DocIr` whose regions are the given paragraphs, in reading order.
99	///
100	/// [`Geometry::DomOrder`] is the honest value: these are reading-order
101	/// placements quantized onto the unit square, NOT measured layout. The IR has
102	/// a variant for exactly that distinction and using `Rendered` here would
103	/// claim a measurement nobody took.
104	fn ir_from_paragraphs(source: &[u8], paras: &[String], prov: Provenance) -> DocIr {
105	    let n = paras.len().max(1);
106	    let regions = paras
107	        .iter()
108	        .enumerate()
109	        .map(|(i, p)| {
110	            let y0 = u8::try_from(i * 255 / n).unwrap_or(u8::MAX);
111	            let y1 = u8::try_from((i + 1) * 255 / n).unwrap_or(u8::MAX);
112	            Region {
113	                kind: RegionKind::Text,
114	                bbox: BBoxRail {
115	                    tl: Rail { x: 0, y: y0 },
116	                    br: Rail { x: 255, y: y1 },
117	                },
118	                // Deliberately NOT the positional index: `2i+1` makes
119	                // "read the field" and "renumber by position" distinguishable.
120	                // With them equal, a gate that renumbers passes identically —
121	                // the fixture's SHAPE is part of the coverage.
122	                reading_order: u16::try_from(i * 2 + 1).unwrap_or(u16::MAX),
123	                text: Some(p.clone()),
124	                cells: Vec::new(),
125	                children: Vec::new(),
126	            }
127	        })
128	        .collect();
129	    DocIr {
130	        version: DOC_IR_VERSION.to_string(),
131	        source: prov,
132	        geometry: Geometry::DomOrder,
133	        content_sha256: Sha256::digest(source).into(),
134	        mime: "text/plain".to_string(),
135	        pages: vec![DocPage {
136	            number: 0,
137	            width: 1,
138	            height: u32::try_from(n).unwrap_or(u32::MAX),
139	            regions,
140	        }],
141	        fields: Vec::new(),
142	    }
143	}
