145	fn kjv() -> Corpus {
146	    let paras: Vec<String> = SCENE.iter().map(|v| (*v).to_string()).collect();
147	    let source = paras.join("\n").into_bytes();
148	    let ir = ir_from_paragraphs(&source, &paras, Provenance::Ocr);
149	    Corpus {
150	        name: "kjv-genesis-scene",
151	        source,
152	        ir,
153	    }
154	}
