156	/// Alice, split into paragraphs. Blank-line separated; a paragraph is a region.
157	fn alice(max_spans: usize) -> Corpus {
158	    // The committed file is CRLF with a BOM. A naive `split("\n\n")` finds
159	    // NOTHING in it — the first version of this probe silently produced ONE
160	    // 169 KB span and every per-span number it printed was meaningless while
161	    // every gate stayed green. Normalising first is what makes the span count
162	    // real.
163	    let raw = include_str!("../corpus/alice.txt")
164	        .trim_start_matches('\u{feff}')
165	        .replace("\r\n", "\n");
166	    let mut paras: Vec<String> = Vec::new();
167	    for para in raw.split("\n\n") {
168	        let p = para.split_whitespace().collect::<Vec<_>>().join(" ");
169	        if p.len() < 40 {
170	            continue;
171	        }
172	        paras.push(p);
173	        if paras.len() >= max_spans {
174	            break;
175	        }
176	    }
177	    let source = paras.join("\n").into_bytes();
178	    let ir = ir_from_paragraphs(&source, &paras, Provenance::Dom);
179	    Corpus {
180	        name: "alice-paragraphs",
181	        source,
182	        ir,
183	    }
184	}
