186	/// `word -> Pos`, from the committed COCA projection. The COCA letter mapping is
187	/// `DeepNSM`'s own; it lives in BOTH of that crate's examples, byte-identical,
188	/// because `deepnsm_v2::lexicon` was DELETED by an earlier audit on the ground
189	/// that `lance-graph-planner`'s `insight_coca_read` already grounds it. That
190	/// grounding does not reach here: `insight_coca_read` is itself an example
191	/// binary in a crate outside this repo's dependency barrier. So re-stating the
192	/// twenty-line tagger is the ONE duplication this seam forces, and the report
193	/// records the deletion rather than quietly re-adding the module.
194	fn coca_pos(letter: &str) -> Pos {
195	    match letter {
196	        "n" | "p" => Pos::Noun,
197	        "v" => Pos::Verb,
198	        "j" => Pos::Adj,
199	        "a" | "d" => Pos::Det,
200	        _ => Pos::Other,
201	    }
202	}
203	
204	fn load_vocab() -> (PaletteVocab, HashMap<String, Pos>) {
205	    let tsv = include_str!("../corpus/coca_academic_20k.tsv");
206	    let mut vocab = PaletteVocab::new();
207	    let mut pos = HashMap::new();
208	    let mut words: Vec<&str> = Vec::new();
209	    for line in tsv.lines() {
210	        let mut it = line.split('\t');
211	        let (Some(w), Some(p)) = (it.next(), it.next()) else {
212	            continue;
213	        };
214	        if w.is_empty() {
215	            continue;
216	        }
217	        words.push(w);
218	        pos.entry(w.to_string()).or_insert_with(|| coca_pos(p));
219	    }
220	    vocab.from_frequency_ranked(words);
221	    (vocab, pos)
222	}
