224	fn pct(a: usize, b: usize) -> f64 {
225	    if b == 0 {
226	        0.0
227	    } else {
228	        100.0 * a as f64 / b as f64
229	    }
230	}
231	
232	fn quantiles(v: &mut [usize]) -> (usize, usize, usize) {
233	    v.sort_unstable();
234	    if v.is_empty() {
235	        return (0, 0, 0);
236	    }
237	    (
238	        v[v.len() / 2],
239	        v[(v.len() * 95) / 100],
240	        *v.last().expect("non-empty"),
241	    )
242	}
