277	/// Tokenize a whole corpus into ONE lane under ONE contract, then measure it.
278	fn ingest(c: &Corpus, contract: &TokenizerContract, g: &mut Gate) -> (TokenLane, Summary) {
279	    let mut lane = TokenLane::new();
280	    let doc = lane.intern_document(c.ir.content_sha256);
281	    let sp = spans(&c.ir, doc);
282	    let mut probes = 0usize;
283	    let mut per_span: Vec<usize> = Vec::new();
284	    let before = source_passes();
285	    for s in &sp {
286	        let (tokens, p) = contract
287	            .try_encode(s.text.as_bytes())
288	            .expect("contract trained on this corpus");
289	        probes += p;
290	        per_span.push(tokens.len().div_ceil(IDS_PER_PARTICLE));
291	        // byte_from is 0: a whole region, and the offset is REGION-LOCAL
292	        // because the region owns its canonical text.
293	        lane.append(s.key, 0, contract, &tokens);
294	    }
295	    let passes = source_passes() - before;
296	    g.run(
297	        &format!(
298	            "T-PASSES[{}] exactly one source tokenization per span",
299	            c.name
300	        ),
301	        passes == sp.len(),
302	        &format!(
303	            "{passes} source tokenizations for {} spans (1.000 per span); the three consumers \
304	             below add ZERO further source passes — every one of them reads the lane",
305	            sp.len()
306	        ),
307	    );
308	
309	    // ---- the receipt is keyed by the DOCUMENT LAYER's address ----
310	    // Independent ground truth: walk the IR directly rather than trusting the
311	    // same `spans()` call under test.
312	    let truth: Vec<(u16, u16)> =
313	        c.ir.pages
314	            .iter()
315	            .flat_map(|pg| pg.regions.iter().map(move |r| (pg.number, r.reading_order)))
316	            .collect();
317	    let key_ok = truth.len() == lane.receipts().len()
318	        && lane
319	            .receipts()
320	            .iter()
321	            .zip(&truth)
322	            .all(|(r, &(page, ro))| {
323	                r.key.page == page
324	                    && r.key.reading_order == ro
325	                    && lane.document_of(r) == Some(&c.ir.content_sha256)
326	            })
327	        // and the orders are genuinely not the positional index, so the check
328	        // above cannot be satisfied by renumbering
329	        && truth.iter().enumerate().any(|(i, &(_, ro))| ro as usize != i);
330	    let reinterned = {
331	        let mut l2 = lane.clone();
332	        let same = l2.intern_document(c.ir.content_sha256);
333	        let other = l2.intern_document([0xAB; 32]);
334	        same == doc && other != doc && l2.document_len() == 2
335	    };
336	    g.run(
337	        &format!(
338	            "T-DOCIR-KEY[{}] the receipt carries no id this crate minted",
339	            c.name
340	        ),
341	        key_ok && reinterned && !sp.is_empty(),
342	        &format!(
343	            "every one of {} receipts resolves to the IR's own address — `content_sha256` for \
344	             WHICH document and `(page, reading_order)` for WHICH span, the reading order \
345	             `ogar-doc-ir` documents as the one the temporal stream and DeepNSM consume. \
346	             Re-interning the same `content_sha256` returns the SAME index and a different one \
347	             does not: that is the S-2 dedup property at lane scope. The hash is interned once \
348	             per document, not stamped on every receipt — at these span sizes a receipt is \
349	             already a third of the resident bytes and 32 more per span would have more than \
350	             doubled that for no addressing gain",
351	            sp.len()
352	        ),
353	    );
354	
355	    // ---- reconstruction + framing ----
356	    let mut recon_ok = true;
357	    let mut tokens_total = 0usize;
358	    let mut uniq = std::collections::HashSet::new();
359	    for (r, sr) in lane.receipts().iter().zip(&sp) {
360	        let v = lane.view(r, contract).expect("same contract");
361	        tokens_total += v.len();
362	        uniq.extend(v.ids().iter().copied());
363	        if v.decode() != sr.text.as_bytes() {
364	            recon_ok = false;
365	        }
366	    }
367	    let (p50, p95, pmax) = quantiles(&mut per_span.clone());
368	    let cont = per_span.iter().filter(|&&n| n > 1).count();
369	    g.run(
370	        &format!(
371	            "T-RECON[{}] every span decodes byte-exact from ids alone",
372	            c.name
373	        ),
374	        recon_ok,
375	        &format!(
376	            "{} spans, {tokens_total} tokens, {} distinct ids; decode reads the lane and the \
377	             codebook and nothing else — the canonical text stays authoritative and is never \
378	             consulted to read a span back",
379	            sp.len(),
380	            uniq.len()
381	        ),
382	    );
383	
384	    // ---- derived offsets ----
385	    let mut off_ok = true;
386	    for (r, sr) in lane.receipts().iter().zip(&sp) {
387	        let v = lane.view(r, contract).expect("same contract");
388	        // Ground truth computed the expensive way: decode each prefix.
389	        let mut cursor = 0u32;
390	        for t in v.tokens() {
391	            let truth_len = contract.decode(&[t.id]).0.len();
392	            if t.byte_from != cursor
393	                || t.byte_to != cursor + u32::try_from(truth_len).expect("short")
394	            {
395	                off_ok = false;
396	            }
397	            cursor = t.byte_to;
398	        }
399	        if cursor as usize != sr.text.len() {
400	            off_ok = false;
401	        }
402	    }
403	    g.run(
404	        &format!(
405	            "T-OFFSET[{}] byte offsets are DERIVED, never stored",
406	            c.name
407	        ),
408	        off_ok,
409	        &format!(
410	            "every token's (byte_from, byte_to) reproduces a decode-the-prefix ground truth, \
411	             and the last token's end lands exactly on the span end; the receipt carries no \
412	             offset column — {} bytes/receipt total, of which zero are offsets per token",
413	            core::mem::size_of::<TokenStreamReceipt>()
414	        ),
415	    );
416	
417	    let summary = Summary {
418	        name: c.name,
419	        bytes: c.source.len(),
420	        spans: sp.len(),
421	        tokens: tokens_total,
422	        uniq_tokens: uniq.len(),
423	        particles: lane.particle_len(),
424	        resident_bytes: lane.resident_bytes(),
425	        p50,
426	        p95,
427	        pmax,
428	        continuation_rate: pct(cont, per_span.len()),
429	        encode_probes: probes,
430	        lex_units: 0,
431	        lex_resolved: 0,
432	        tokens_per_unit: (0, 0, 0),
433	        multi_unit_tokens: 0,
434	        spo: 0,
435	    };
436	    (lane, summary)
437	}
