439	/// Consumer B: the DeepNSM-v2 projection, run from ids alone.
440	fn deepnsm_arm(
441	    c: &Corpus,
442	    contract: &TokenizerContract,
443	    lane: &TokenLane,
444	    vocab: &PaletteVocab,
445	    posmap: &HashMap<String, Pos>,
446	    s: &mut Summary,
447	    g: &mut Gate,
448	) {
449	    let before = source_passes();
450	    let mut units = 0usize;
451	    let mut resolved = 0usize;
452	    let mut spans_per_unit: Vec<usize> = Vec::new();
453	    let mut multi_unit_tokens = 0usize;
454	    let mut triples: Vec<Spo> = Vec::new();
455	    let mut flattened: Vec<Spo> = Vec::new();
456	    let mut offsets_ok = true;
457	
458	    let sp = spans(&c.ir, 0);
459	    for (r, sr) in lane.receipts().iter().zip(&sp) {
460	        let v = lane.view(r, contract).expect("same contract");
461	        let lex = project(&v);
462	        // A token that carries more than one unit's start is a token straddling
463	        // a word boundary — the cardinality that refutes any 1:1 assumption.
464	        let mut starts: HashMap<u32, usize> = HashMap::new();
465	        let mut tagged: Vec<Tagged> = Vec::new();
466	        for u in &lex {
467	            units += 1;
468	            spans_per_unit.push(u.token_span as usize);
469	            *starts.entry(u.first_token).or_insert(0) += 1;
470	            // The unit's byte span must address the canonical text and land on
471	            // exactly the bytes it claims (modulo the normalisation that drops
472	            // non-alphabetic characters inside a word).
473	            let raw = &sr.text.as_bytes()[u.byte_from as usize..u.byte_to as usize];
474	            let renorm: String = raw
475	                .iter()
476	                .filter(|b| b.is_ascii_alphabetic())
477	                .map(|b| b.to_ascii_lowercase() as char)
478	                .collect();
479	            if renorm != u.surface {
480	                offsets_ok = false;
481	            }
482	            if let Some(id) = vocab.id(&u.surface) {
483	                resolved += 1;
484	                let pos = posmap.get(&u.surface).copied().unwrap_or(Pos::Other);
485	                tagged.push(Tagged::new(id, pos));
486	            }
487	        }
488	        multi_unit_tokens += starts.values().filter(|&&n| n > 1).count();
489	        tagged.push(Tagged::new(0, Pos::Stop));
490	        triples.extend(parse_to_spo(&tagged));
491	        // Control: the SAME word ids with every tag flattened to Noun. If the
492	        // FSM's output did not depend on the Pos half of the pair, this would
493	        // produce the same triples — and "the FSM consumes (WordId, Pos)"
494	        // would be a claim about a type signature rather than about behaviour.
495	        let blind: Vec<Tagged> = tagged
496	            .iter()
497	            .map(|t| {
498	                Tagged::new(
499	                    t.id,
500	                    if t.pos == Pos::Stop {
501	                        Pos::Stop
502	                    } else {
503	                        Pos::Noun
504	                    },
505	                )
506	            })
507	            .collect();
508	        flattened.extend(parse_to_spo(&blind));
509	    }
510	    let passes = source_passes() - before;
511	    let (q50, q95, qmax) = quantiles(&mut spans_per_unit.clone());
512	
513	    g.run(
514	        &format!(
515	            "T-DEEPNSM[{}] projection runs from ids alone, zero source passes",
516	            c.name
517	        ),
518	        passes == 0 && units > 0,
519	        &format!(
520	            "{units} lexical units from {} tokens with {passes} additional source \
521	             tokenizations — `project()` takes a borrowed view and NO source bytes, so \
522	             re-reading the source is unavailable rather than merely avoided",
523	            s.tokens
524	        ),
525	    );
526	    g.run(
527	        &format!(
528	            "T-DEEPNSM-SPAN[{}] every unit's byte span addresses the canonical text",
529	            c.name
530	        ),
531	        offsets_ok,
532	        "each unit's (byte_from, byte_to) slice of the canonical text re-normalises to exactly \
533	         the surface the projection produced from ids — the seam's span identity is real, not \
534	         nominal",
535	    );
536	    g.run(
537	        &format!(
538	            "T-DEEPNSM-CARD[{}] the BPE:word cardinality is measured, not assumed",
539	            c.name
540	        ),
541	        qmax > 1 && multi_unit_tokens > 0 && q50 >= 1,
542	        &format!(
543	            "tokens per lexical unit p50={q50} p95={q95} max={qmax}; {multi_unit_tokens} tokens \
544	             carry the start of MORE THAN ONE unit (a token straddling a word boundary). \
545	             Neither direction is 1:1 — BPE sequence identity and the DeepNSM word coordinate \
546	             are different id spaces, exactly as the fence requires"
547	        ),
548	    );
549	    g.run(
550	        &format!(
551	            "T-DEEPNSM-FSM[{}] the FSM consumes (WordId, Pos) with no strings",
552	            c.name
553	        ),
554	        !triples.is_empty() && flattened.is_empty() && resolved * 2 > units,
555	        &format!(
556	            "{}/{units} units resolved to a PaletteVocab WordId ({:.1}% ; {:.1}% OOV against a \
557	             {}-word academic vocabulary), and `parse_to_spo` emitted {} SPO triples. The Pos \
558	             half is load-bearing, not decorative: the SAME word ids with every tag flattened to \
559	             Noun emit {} triples, so the FSM's output genuinely depends on the pair and this \
560	             gate is not a restatement of a type signature. DeepNSM-v2 needed NO change — its \
561	             library is already tokenizer-free, the split_whitespace lives only in its examples",
562	            resolved,
563	            pct(resolved, units),
564	            100.0 - pct(resolved, units),
565	            vocab.len(),
566	            triples.len(),
567	            flattened.len()
568	        ),
569	    );
570	    s.lex_units = units;
571	    s.lex_resolved = resolved;
572	    s.tokens_per_unit = (q50, q95, qmax);
573	    s.multi_unit_tokens = multi_unit_tokens;
574	    s.spo = triples.len();
575	}
