577	/// What one Tantivy index measured.
578	struct IndexStats {
579	    segments: usize,
580	    terms: usize,
581	    docs: u64,
582	    total_tokens: u64,
583	    bytes: usize,
584	    phrase_hits: usize,
585	}
586	
587	/// Consumer A: Tantivy, driven by receipt handles. The index never sees text.
588	fn tantivy_arm(
589	    store: &Arc<SeamStore>,
590	    mode: TermMode,
591	    probe_receipt: usize,
592	    g: &mut Gate,
593	    label: &str,
594	) -> IndexStats {
595	    let mut sb = Schema::builder();
596	    let opts = TextOptions::default().set_stored().set_indexing_options(
597	        TextFieldIndexing::default()
598	            .set_tokenizer("receipt")
599	            .set_index_option(IndexRecordOption::WithFreqsAndPositions),
600	    );
601	    let body = sb.add_text_field("body", opts);
602	    let schema = sb.build();
603	    let index = Index::create_in_ram(schema);
604	    index
605	        .tokenizers()
606	        .register("receipt", ReceiptTokenizer::new(Arc::clone(store), mode));
607	
608	    let n = store.lane.receipts().len();
609	    let before_src = source_passes();
610	    let before_q = query_passes();
611	    {
612	        // ONE indexing thread => ONE segment. The first version used the
613	        // default writer, which spreads documents across threads and therefore
614	        // across segments; summing `num_terms()` over segments then reported
615	        // 202 terms for a lane holding 137 distinct ids. A term count that
616	        // exceeds the vocabulary is the signature of that mistake.
617	        let mut w: IndexWriter = index
618	            .writer_with_num_threads(1, 50_000_000)
619	            .expect("writer");
620	        for i in 0..n {
621	            let mut d = TantivyDocument::default();
622	            // The FIELD VALUE IS A HANDLE, not the text. This is what makes
623	            // re-tokenization structurally impossible rather than merely
624	            // discouraged.
625	            d.add_text(body, handle(i));
626	            w.add_document(d).expect("add");
627	        }
628	        w.commit().expect("commit");
629	    }
630	    let src_passes = source_passes() - before_src;
631	    let q_passes = query_passes() - before_q;
632	
633	    let reader = index.reader().expect("reader");
634	    let searcher = reader.searcher();
635	    let mut terms = 0usize;
636	    let mut total_tokens = 0u64;
637	    let segments = searcher.segment_readers().len();
638	    for seg in searcher.segment_readers() {
639	        let inv = seg.inverted_index(body).expect("inverted index");
640	        terms += inv.terms().num_terms();
641	        total_tokens += inv.total_num_tokens();
642	    }
643	    let dir = index.directory();
644	    let bytes: usize = dir
645	        .list_managed_files()
646	        .iter()
647	        .filter_map(|p| dir.open_read(p).ok())
648	        .map(|f| {
649	            use tantivy::HasLen as _;
650	            f.len()
651	        })
652	        .sum();
653	
654	    // ---- positions must BE the receipt's positions ----
655	    let mut analyzer = index.tokenizers().get("receipt").expect("registered");
656	    let h = handle(probe_receipt);
657	    let mut seen: Vec<usize> = Vec::new();
658	    {
659	        let mut ts = analyzer.token_stream(&h);
660	        while ts.advance() {
661	            seen.push(ts.token().position);
662	        }
663	    }
664	    let r = store.lane.receipts()[probe_receipt];
665	    let expect: Vec<usize> = (0..r.token_count as usize).collect();
666	    g.run(
667	        &format!("T-TANTIVY-POS[{label}] index positions ARE receipt positions"),
668	        seen == expect,
669	        &format!(
670	            "receipt {probe_receipt} has token_count={} and the analyzer registered on the index \
671	             yields positions 0..{} in order — no drift, because there is only one segmentation \
672	             and the index consumed it",
673	            r.token_count, r.token_count
674	        ),
675	    );
676	    g.run(
677	        &format!("T-TANTIVY-NOSRC[{label}] indexing tokenized NOTHING, by either counter"),
678	        src_passes == 0 && q_passes == 0,
679	        &format!(
680	            "{n} documents indexed, {src_passes} source + {q_passes} query tokenizations. Both \
681	             counters are asserted: during INDEXING any tokenization at all is a \
682	             re-tokenization, and handing Tantivy the raw text instead of a handle would take \
683	             the fallback path and bump the QUERY counter — a source-only assertion would have \
684	             stayed green through exactly the mistake it exists to catch"
685	        ),
686	    );
687	
688	    // ---- a phrase query over the SAME segmentation ----
689	    let ids: Vec<u8> = {
690	        let v = store.lane.view(&r, &store.contract).expect("same contract");
691	        v.ids().iter().copied().take(3).collect()
692	    };
693	    let phrase: Vec<Term> = ids
694	        .iter()
695	        .map(|&id| {
696	            let text = match mode {
697	                TermMode::Surface => {
698	                    String::from_utf8_lossy(store.contract.surface(id)).to_string()
699	                }
700	                TermMode::TokenId => format!("{id:02x}"),
701	            };
702	            Term::from_field_text(body, &text)
703	        })
704	        .collect();
705	    let (hits, stored) = if phrase.len() >= 2 {
706	        let q = PhraseQuery::new(phrase);
707	        let top = searcher
708	            .search(&q, &TopDocs::with_limit(10).order_by_score())
709	            .expect("search");
710	        let stored = top.first().map_or_else(String::new, |(_, addr)| {
711	            let d: TantivyDocument = searcher.doc(*addr).expect("doc");
712	            d.get_first(body)
713	                .and_then(|v| v.as_str().map(str::to_string))
714	                .unwrap_or_default()
715	        });
716	        (top.len(), stored)
717	    } else {
718	        (0, String::new())
719	    };
720	    g.run(
721	        &format!("T-TANTIVY-PHRASE[{label}] a phrase over the shared segmentation retrieves"),
722	        hits > 0 && stored == handle(probe_receipt),
723	        &format!(
724	            "a 3-token phrase taken straight out of receipt {probe_receipt}'s ids matched {hits} \
725	             document(s) via POSITIONS ONLY, and the top hit's stored field is exactly \
726	             \"{stored}\" — the receipt the phrase came FROM, not merely some handle-shaped \
727	             value (every document in this index starts with the handle prefix, so a \
728	             prefix check would have been unconditional). Tantivy persists term + position and never writes \
729	             offset_from/offset_to at all (measured in this fork: the indexer's `index_text` \
730	             reads `text` and `position`, uses `position_length` transiently, and reads the \
731	             offsets nowhere outside its own tests), so the index cannot become the owner of \
732	             offsets even by accident"
733	        ),
734	    );
735	
736	    IndexStats {
737	        segments,
738	        terms,
739	        docs: searcher.num_docs(),
740	        total_tokens,
741	        bytes,
742	        phrase_hits: hits,
743	    }
744	}
