746	/// Lines of Rust that are not comments — the fence must not be satisfied by
747	/// its own prose.
748	fn code_lines(src: &str) -> String {
749	    src.lines()
750	        .filter(|l| {
751	            let t = l.trim_start();
752	            !(t.starts_with("//") || t.starts_with("/*") || t.starts_with('*'))
753	        })
754	        .collect::<Vec<_>>()
755	        .join("\n")
756	}
