758	fn main() {
759	    let mut g = Gate { pass: 0 };
760	    println!("PROBE-TOKEN-SEAM-1 — one receipt, three borrowed consumers\n");
761	
762	    let (vocab, posmap) = load_vocab();
763	    let corpora = [kjv(), alice(300)];
764	
765	    // ---- T-CORPUS ----
766	    // The unicode-whitespace divergence, BOUNDED by measurement rather than by
767	    // hope: DeepNSM splits on `char::is_whitespace` (Unicode), this projection
768	    // splits on `u8::is_ascii_whitespace`. They differ only where a corpus
769	    // contains non-ASCII whitespace, so the probe counts it instead of
770	    // assuming it away.
771	    let exotic_ws: usize = corpora
772	        .iter()
773	        .map(|c| {
774	            String::from_utf8_lossy(&c.source)
775	                .chars()
776	                .filter(|ch| ch.is_whitespace() && !ch.is_ascii_whitespace())
777	                .count()
778	        })
779	        .sum();
780	    g.run(
781	        "T-CORPUS committed, real, hermetic; span population and the unicode-whitespace \
782	         divergence both measured",
783	        corpora.iter().all(|c| c.source.len() > 1000)
784	            && spans(&corpora[0].ir, 0).len() >= 8
785	            && spans(&corpora[1].ir, 0).len() >= 100
786	            && vocab.len() > 10_000
787	            && exotic_ws == 0,
788	        &format!(
789	            "{} ({} bytes, {} spans) and {} ({} bytes, {} spans), both committed in-repo; \
790	             DeepNSM vocabulary {} words from the committed COCA projection. ABSENT and NOT \
791	             simulated: whole-KJV, bible_vocab.txt, the trained cam96 codebook/codes (so the \
792	             semantic DISTANCE half of DeepNSM cannot be exercised here), and any MecCog corpus \
793	             — which exists nowhere on this machine. The span COUNT is asserted, not just \
794	             the byte count: the CRLF split bug this probe hit left every byte total healthy \
795	             while collapsing 300 spans into 1. Non-ASCII whitespace, on which this \
796	             projection's byte-level split would legitimately diverge from DeepNSM's \
797	             char-level `is_whitespace`, occurs {exotic_ws} times across both corpora — the \
798	             divergence is bounded by measurement, and named as a gap rather than denied",
799	            corpora[0].name,
800	            corpora[0].source.len(),
801	            spans(&corpora[0].ir, 0).len(),
802	            corpora[1].name,
803	            corpora[1].source.len(),
804	            spans(&corpora[1].ir, 0).len(),
805	            vocab.len()
806	        ),
807	    );
