809	    // ---- T-DOCIR: through the IR's OWN closed-vocabulary gate ----
810	    let mut roundtrip_ok = true;
811	    let mut sha_ok = true;
812	    for c in &corpora {
813	        let json = to_json(&c.ir).expect("serialize");
814	        match from_json(&json) {
815	            Ok(back) => {
816	                if back != c.ir {
