818	                }
819	            }
820	            Err(_) => roundtrip_ok = false,
821	        }
822	        if c.ir.content_sha256 != <[u8; 32]>::from(Sha256::digest(&c.source)) {
823	            sha_ok = false;
824	        }
825	    }
826	    // The gate must also REFUSE: swap a region kind for one outside the closed
827	    // vocabulary and the IR's own loader has to reject it, or "closed" is a
828	    // word rather than a mechanism. Same for a version bump.
829	    let off_vocab = to_json(&corpora[0].ir)
830	        .expect("serialize")
831	        .replace("\"kind\":\"text\"", "\"kind\":\"paragraph\"");
832	    let refused = from_json(&off_vocab).is_err();
833	    let wrong_version = to_json(&corpora[0].ir)
